<template>
  <div ref="chartElem" class="chart-wrap"></div>
</template>

<script>
import { renderCPULine } from "@/assets/utils/chartUtils";
export default {
  props: {
    dataList: {
      type: Array,
      default: () => {
        return [];
      },
    },
    chartsObj: {
      type: Object,
      default: () => {
        return {
          xData: [],
        };
      },
    },
  },
  data() {
    return {};
  },
  mounted() {
    this.$nextTick(() => {
      this.getCharts();
    });
  },
  watch: {
    dataList: {
      handler() {
      this.$nextTick(this.getCharts)
      },
      deep: true,
      immediate: true,
    },
  },
  methods: {
    getCharts() {
      renderCPULine(this.$refs.chartElem, this.dataList, this.chartsObj);
    },
  },
};
</script>

<style lang="scss" scoped>
.chart-wrap {
  height: 100%;
  width: 100%;
}
</style>
