import * as echarts from "echarts";

const xAxisConfig = {
  nameLocation: "start",
  nameTextStyle: {
    color: "#333",
    fontSize: 12,
    padding: [30, 5, 0, 0],
    align: "right",
  },
  // type: 'category',
  boundaryGap: true,
  axisLine: {
    //坐标轴轴线相关设置。数学上的x轴
    show: false,
    lineStyle: {
      color: "rgba(0, 0, 0, 0.4)",
    },
  },
  axisLabel: {
    //坐标轴刻度标签的相关设置
    // textStyle: {
    color: "#999",
    padding: 2,
    fontSize: 12,
    // },
  },
  splitLine: {
    show: false,
  },
};
const yAxisConfig = {
  nameTextStyle: {
    color: "#333",
    fontSize: 14,
    padding: 0,
    align: "right",
  },
  min: 0,
  splitLine: {
    show: true,
    lineStyle: {
      color: "rgba(0,0,0, 0.1)",
    },
  },
  axisLine: {
    show: false,
  },
  axisLabel: {
    show: true,
    // textStyle: {
    color: "#999",
    padding: 0,
    // },
  },
  axisTick: {
    show: false,
  },
};

/**
 * 渲染CPU监控折线图
 * @param {HTMLElement} elem - DOM容器元素
 * @param {Array} dataList - 数据列表
 * @param {Object} options - 配置选项
 */
export function renderCPULine(
  elem,
  dataList,
  {
    xData,
    xName,
    yName,
    yMax = "dataMax",
    unit,
    symbolSize = 4,
    smooth = true,
    showLegend = true,
  }
) {
  // 检查并销毁旧实例
  let chart = echarts.getInstanceByDom(elem);
  if (chart) {
    chart.dispose();
  }
  chart = echarts.init(elem);

  // 处理数据系列
  const series = [];
  const optionColor = [];

  dataList.forEach((item) => {
    const lineColor = item.color;
    const itemColor = [hexToRgba(item.color, 0.1), hexToRgba(item.color, 0.3)];
    optionColor.push(lineColor);

    series.push({
      name: item.name,
      type: "line",
      symbolSize: symbolSize,
      smooth: smooth,
      lineStyle: {
        width: 1.3,
        color: lineColor,
        type: "solid",
      },
      tooltip: { show: true },
      label: { show: false },
      areaStyle: {
        color: new echarts.graphic.LinearGradient(
          0,
          0,
          0,
          1,
          [
            { offset: 0, color: itemColor[0] },
            { offset: 1, color: itemColor[1] },
          ],
          false
        ),
      },
      data: item.valueList,
    });
  });

  // 配置坐标轴
  const xAxis = Object.assign({}, xAxisConfig, {
    name: xName,
    data: xData,
    boundaryGap: false,
  });

  const yAxis = Object.assign(yAxisConfig, {
    name: unit ? `${yName}(${unit})` : yName,
    max: yMax || "auto",
    splitNumber: 10,
  });

  // 完整配置项
  const option = {
    animation: false,
    color: optionColor,
    grid: {
      top: "10%",
      left: 15,
      right: 15,
      bottom: 25,
      containLabel: true,
    },
    tooltip: {
      trigger: "axis",
      formatter(params) {
        var relVal = params[0].name;
        for (var i = 0, l = params.length; i < l; i++) {
          relVal +=
            "<br/>" +
            params[i].marker +
            params[i].seriesName +
            " : " +
            params[i].value +
            "%";
        }
        return relVal;
      },
    },
    legend: showLegend
      ? {
          data: dataList.map((item) => item.name),
          right: 10,
          top: 10,
          textStyle: { color: "#666" },
        }
      : null,
    xAxis,
    yAxis,
    series,
  };

  // 渲染图表
  chart.setOption(option);

  // 窗口大小变化时自适应
  window.addEventListener("resize", function () {
    chart.resize();
  });

  return chart;
}

/**
 * 16进制颜色转RGBA
 */
function hexToRgba(hex, opacity) {
  const r = parseInt(hex.slice(1, 3), 16);
  const g = parseInt(hex.slice(3, 5), 16);
  const b = parseInt(hex.slice(5, 7), 16);
  return `rgba(${r}, ${g}, ${b}, ${opacity})`;
}
